"kind": "propose",
"summary": "The container's CPU limit is too low, causing high usage and readiness probe failures. Increasing the CPU limit to 750m should alleviate the issue.",
"hypotheses": [
  {
    "root_cause_class": "cpu_limit_too_low",
    "summary": "The container's CPU usage is near its limit (0.495/0.5), and readiness probes are failing, indicating the limit is too low.",
    "supporting": ["ev-container_cpu", "ev-target_events"],
    "contradicting": [],
    "missing": ["throttling_data_available"],
    "status": "supported"
  }
],
"proposal": {
  "capability": "deployment.set-resources",
  "target": {
    "group": "apps",
    "kind": "Deployment",
    "namespace": "shop",
    "name": "search",
    "uid": "uid-deployment-search"
  },
  "params": {
    "containers": {
      "api": {
        "limits": {
          "cpu": "750m"
        }
      }
    }
  },
  "expected_effect": "The increased CPU limit should prevent the container from being throttled, allowing it to meet readiness probe requirements.",
  "rationale": "The container is using 99% of its CPU limit (0.495/0.5), and readiness probes are failing. Raising the limit to 750m (1.5x current) should clear the throttling and resolve the timeouts.",
  "cited_evidence_ids": ["ev-container_cpu", "ev-target_events"],
  "cited_predicates": ["cpu_usage_near_limit", "rollout_recent"]
}
}
